// Code Node: Подготовка одного рецепта для OpenAI Embeddings
// Размещается после Split In Batches, перед HTTP Request к OpenAI

const recipe = $input.first().json;


// Создаем текст для эмбеддинга
const fullText = `Рецепт: ${recipe.name}\n\nСодержание: ${recipe.content}`;

// Ограничиваем размер текста (OpenAI имеет лимит ~8191 токенов)
// Примерно 1 токен = 4 символа, оставляем запас
const MAX_CHARS = 7000; // ~1750 токенов

let embeddingText;
if (fullText.length <= MAX_CHARS) {
  embeddingText = fullText;
  console.log(`Текст помещается: ${fullText.length} символов`);
} else {
  // Обрезаем по границе слов
  const truncated = fullText.substring(0, MAX_CHARS);
  const lastSpaceIndex = truncated.lastIndexOf(' ');

  // Если последний пробел не слишком далеко, обрезаем по нему
  if (lastSpaceIndex > MAX_CHARS * 0.9) {
    embeddingText = truncated.substring(0, lastSpaceIndex) + '...';
  } else {
    embeddingText = truncated + '...';
  }

  console.log(`Текст обрезан: ${fullText.length} → ${embeddingText.length} символов`);
}

// Возвращаем данные для OpenAI
return [{
  json: {
    model: "text-embedding-3-small",
    input: embeddingText,
    // Сохраняем оригинальные данные рецепта для следующего шага
    recipe_data: {
      id: recipe.id,
      number: recipe.number,
      name: recipe.name,
      content: recipe.content,
      full_text: recipe.full_text,
      sparse_vectors: recipe.sparse_vectors,
      // Добавляем информацию об обрезке
      was_truncated: fullText.length > MAX_CHARS,
      original_length: fullText.length,
      embedding_length: embeddingText.length
    }
  }
}];

// Расширенный парсер рецептов для всех типов (водки, ликёры, масла, бальзамы, благовонные воды)
console.log('=== РАСШИРЕННЫЙ ПАРСИНГ ВСЕХ ТИПОВ РЕЦЕПТОВ ===');

// Функция обработки словарей (без изменений)
function processVocabularies(vocabularyData) {
  console.log('⏳ Обрабатываем словари...');

  if (!Array.isArray(vocabularyData) || vocabularyData.length === 0) {
    throw new Error('Словари пусты или неверного формата');
  }

  const vocabularies = {};
  const categoryStats = {};

  for (const row of vocabularyData) {
    const { category, term, term_index, weight_multiplier } = row;

    if (!category || !term || term_index === undefined) {
      throw new Error(`Некорректные данные: ${JSON.stringify(row)}`);
    }

    if (!vocabularies[category]) {
      vocabularies[category] = { terms: [], weights: [] };
      categoryStats[category] = 0;
    }

    vocabularies[category].terms[term_index] = term;
    vocabularies[category].weights[term_index] = parseFloat(weight_multiplier);
    categoryStats[category]++;
  }

  const requiredCategories = ['ingredients', 'spices_herbs', 'techniques', 'categories', 'measurements'];
  const missingCategories = requiredCategories.filter(cat => !vocabularies[cat] || vocabularies[cat].terms.length === 0);

  if (missingCategories.length > 0) {
    throw new Error(`Отсутствуют категории: ${missingCategories.join(', ')}`);
  }

  console.log('✓ Статистика словарей:');
  Object.entries(categoryStats).forEach(([category, count]) => {
    console.log(`  ${category}: ${count} терминов`);
  });

  return vocabularies;
}

// Функция генерации sparse vectors с учетом типа рецепта
function generateSparseVectors(recipeText, recipeName, category, vocabularies) {
  const result = {};

  Object.keys(vocabularies).forEach(cat => {
    result[cat] = { indices: [], values: [] };
  });

  const text = (recipeText + ' ' + recipeName).toLowerCase();

  Object.keys(vocabularies).forEach(cat => {
    const categoryData = vocabularies[cat];

    categoryData.terms.forEach((term, index) => {
      if (!term) return;

      const normalizedTerm = term.toLowerCase();
      if (text.includes(normalizedTerm)) {
        const regex = new RegExp(normalizedTerm.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi');
        const frequency = (text.match(regex) || []).length;

        let weight = frequency * (categoryData.weights[index] || 1.0);

        // Применяем весовые коэффициенты по типу рецепта
        if (category === 'ликёр' && (cat === 'spices_herbs' || cat === 'techniques')) {
          weight *= 1.3;
        } else if (category === 'благовонная_вода' && cat === 'spices_herbs') {
          weight *= 1.5;
        } else if (category === 'ароматическое_масло' && cat === 'ingredients') {
          weight *= 1.4;
        } else if (category === 'бальзам' && cat === 'techniques') {
          weight *= 1.2;
        }

        result[cat].indices.push(index);
        result[cat].values.push(weight);
      }
    });
  });

  return result;
}

// Парсинг благовонных вод (§ 441-483)
function parsePerfumeWaters(text, vocabularies, startRecipeNumber) {
  console.log('\n--- Парсинг благовонных вод ---');
  const recipes = [];
  let nextRecipeNumber = startRecipeNumber;

  // Паттерн для благовонных вод: § номер.\nномер. Название.\nФранцузское название.\n\nСодержание
  const perfumePattern = /§\s*(\d+)\.\s*\n(\d+)\.\s*([^\n]+?)\.\s*\n([^\n]*?)\.?\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let match;
  while ((match = perfumePattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(match[1]);
    const recipeNumber = parseInt(match[2]);
    let name = match[3].trim();
    const frenchName = match[4].trim();
    let content = match[5].trim();

    // Проверяем, что это действительно рецепт
    if (content.length > 100 && 
        (content.includes('Возьми') || content.includes('К приготовлению') || content.includes('настаивать'))) {

      // Нормализуем название
      if (!name.toLowerCase().includes('вода')) {
        name = `Вода ${name}`;
      }

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        french_name: frenchName,
        content: content,
        full_text: `${name}\n${frenchName ? frenchName + '\n' : ''}\n${content}`,
        source_pattern: 'perfume_water',
        category: 'благовонная_вода',
        source_book: 'perfume',
        original_paragraph: paragraphNumber,
        original_recipe_number: recipeNumber,
        sparse_vectors: generateSparseVectors(content, name, 'благовонная_вода', vocabularies)
      });

      console.log(`  ✓ ${name} (§${paragraphNumber}.${recipeNumber})`);
      nextRecipeNumber++;
    }
  }

  console.log(`Найдено ${recipes.length} благовонных вод`);
  return { recipes, nextRecipeNumber };
}

// Парсинг ароматических масел (§ 484-575)
function parseAromaticOils(text, vocabularies, startRecipeNumber) {
  console.log('\n--- Парсинг ароматических масел ---');
  const recipes = [];
  let nextRecipeNumber = startRecipeNumber;

  // Паттерн для простых масел: § номер.\nНазвание.\n\nСодержание
  const oilSimplePattern = /§\s*(\d+)\.\s*\n([^\n]+?)\.\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let match;
  while ((match = oilSimplePattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(match[1]);
    let name = match[2].trim();
    let content = match[3].trim();

    // Пропускаем заголовки глав и коротки записи
    if (name.includes('ГЛАВА') || name.includes('О приготовлении') || content.length < 100) {
      continue;
    }

    // Проверяем, что это рецепт масла
    if ((name.toLowerCase().includes('масло') || name.toLowerCase().includes('oleum')) &&
        content.length > 80 && 
        (content.includes('Возьми') || content.includes('растолки') || content.includes('перегони'))) {

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        content: content,
        full_text: `${name}\n\n${content}`,
        source_pattern: 'aromatic_oil',
        category: 'ароматическое_масло',
        source_book: 'oils',
        original_paragraph: paragraphNumber,
        sparse_vectors: generateSparseVectors(content, name, 'ароматическое_масло', vocabularies)
      });

      console.log(`  ✓ ${name} (§${paragraphNumber})`);
      nextRecipeNumber++;
    }
  }

  console.log(`Найдено ${recipes.length} ароматических масел`);
  return { recipes, nextRecipeNumber };
}

// Парсинг нумерованных рецептов (масла ликёрные и бальзамы)
function parseNumberedRecipes(text, vocabularies, startRecipeNumber) {
  console.log('\n--- Парсинг нумерованных рецептов (ликёрные масла и бальзамы) ---');
  const recipes = [];
  let nextRecipeNumber = startRecipeNumber;

  // Паттерн для нумерованных рецептов: § номер.\nномер. Название.\n\nСодержание
  const numberedPattern = /§\s*(\d+)\.\s*\n(\d+)\.\s*([^\n]+?)\.\s*\n\s*\n([\s\S]*?)(?=§\s*\d+\.|$)/g;

  let match;
  while ((match = numberedPattern.exec(text)) !== null) {
    const paragraphNumber = parseInt(match[1]);
    const recipeNumber = parseInt(match[2]);
    let name = match[3].trim();
    let content = match[4].trim();

    // Проверяем, что это действительно рецепт
    if (content.length > 100 && 
        (content.includes('Возьми') || content.includes('Возьмите') || content.includes('растолки'))) {

      let category, sourceBook;

      // Определяем тип рецепта по названию и содержимому
      if (name.toLowerCase().includes('масло')) {
        category = 'ликёрное_масло';
        sourceBook = 'liqueur_oils';
      } else if (name.toLowerCase().includes('бальзам')) {
        category = 'бальзам';
        sourceBook = 'balsams';
      } else {
        // По умолчанию, если неясно
        category = 'ароматическое_масло';
        sourceBook = 'oils';
      }

      recipes.push({
        id: `recipe_${nextRecipeNumber}`,
        number: nextRecipeNumber,
        name: name,
        content: content,
        full_text: `${name}\n\n${content}`,
        source_pattern: 'numbered_recipe',
        category: category,
        source_book: sourceBook,
        original_paragraph: paragraphNumber,
        original_recipe_number: recipeNumber,
        sparse_vectors: generateSparseVectors(content, name, category, vocabularies)
      });

      console.log(`  ✓ ${name} (${category}, §${paragraphNumber}.${recipeNumber})`);
      nextRecipeNumber++;
    }
  }

  console.log(`Найдено ${recipes.length} нумерованных рецептов`);
  return { recipes, nextRecipeNumber };
}

// Основная функция парсинга (расширенная)
async function parseAllHistoricalRecipes(text, vocabularies) {
  const allRecipes = [];

  console.log('\nНачинаем полный парсинг всех типов рецептов...');
  console.log(`📄 Общая длина текста: ${text.length} символов`);

  // ДИАГНОСТИКА контента
  const diagnostics = {
    hasStarredPatterns: !!text.match(/\*\*\d+\./),
    hasSectionPatterns: !!text.match(/§\s*\d+\./),
    hasPerfumeSection: !!text.match(/О приготовлении душистых.*вод/i),
    hasOilSection: !!text.match(/О приготовлении разных масел/i),
    hasBalsamSection: !!text.match(/О приготовлении бальзамов/i),
    starredCount: (text.match(/\*\*\d+\./g) || []).length,
    sectionCount: (text.match(/§\s*\d+\./g) || []).length
  };

  console.log('🔍 Диагностика содержимого:');
  Object.entries(diagnostics).forEach(([key, value]) => {
    console.log(`  ${key}: ${value}`);
  });

  let nextRecipeNumber = 1;

  try {
    // 1. Парсим рецепты водок (как и раньше)
    console.log('\n--- Ищем рецепты водок ---');
    const vodkaPattern = /\*\*(\d+)\.\s*([^*\n]+?)\*\*([\s\S]*?)(?=\*\*\d+\.|$)/g;
    let match;
    let foundVodkaCount = 0;

    while ((match = vodkaPattern.exec(text)) !== null) {
      const number = parseInt(match[1]);
      const name = match[2].trim().replace(/\.$/, '');
      let content = match[3].trim().replace(/^\s*\n+/, '');

      const isChapterHeader = name.includes('ГЛАВА') || name.includes('§') || content.length < 50;

      if (!isChapterHeader && name.length > 3 && content.length > 30) {
        allRecipes.push({
          id: `recipe_${number}`,
          number: number,
          name: name,
          content: content,
          full_text: `${name}\n\n${content}`,
          source_pattern: 'starred_number_title',
          category: 'водка',
          source_book: 'original',
          sparse_vectors: generateSparseVectors(content, name, 'водка', vocabularies)
        });

        foundVodkaCount++;
        if (foundVodkaCount <= 5) {
          console.log(`  Водка ${number}: "${name}"`);
        }
        nextRecipeNumber = Math.max(nextRecipeNumber, number + 1);
      }
    }
    console.log(`✓ Найдено ${foundVodkaCount} рецептов водок`);

    // 2. Парсим французские ликёры (как и раньше, но сокращенно)
    console.log('\n--- Ищем французские ликёры ---');
    let foundFrenchCount = 0;

    const frenchSections = text.split(/(?=§\s*\d+\.)/);
    for (let i = 0; i < frenchSections.length; i++) {
      const section = frenchSections[i];
      if (section.length < 200) continue;

      const recipePattern = /^(\d+)\.\s*([^\n]+?)\.?\s*\n([\s\S]*?)(?=^\d+\.|$)/gm;
      let recipeMatch;

      while ((recipeMatch = recipePattern.exec(section)) !== null) {
        const recipeNumber = parseInt(recipeMatch[1]);
        let nameAndFrench = recipeMatch[2].trim();
        let content = recipeMatch[3].trim();

        // Простая проверка на ликёр
        const hasIngredients = content.match(/(?:Возьми|французской водки|настаивать)/i);
        const isTableOfContents = content.length < 80;

        if (hasIngredients && !isTableOfContents && content.length > 50) {
          let displayName = nameAndFrench.startsWith('Вода ') ? 
            nameAndFrench.replace('Вода ', 'Ликёр ') : `Ликёр ${nameAndFrench}`;

          allRecipes.push({
            id: `recipe_${nextRecipeNumber}`,
            number: nextRecipeNumber,
            name: displayName,
            content: content,
            full_text: `${displayName}\n\n${content}`,
            source_pattern: 'french_section',
            category: 'ликёр',
            source_book: 'french',
            original_recipe_number: recipeNumber,
            sparse_vectors: generateSparseVectors(content, displayName, 'ликёр', vocabularies)
          });

          foundFrenchCount++;
          nextRecipeNumber++;
        }
      }
    }
    console.log(`✓ Найдено ${foundFrenchCount} французских ликёров`);

    // 3. НОВОЕ: Парсим благовонные воды
    const perfumeResult = parsePerfumeWaters(text, vocabularies, nextRecipeNumber);
    allRecipes.push(...perfumeResult.recipes);
    nextRecipeNumber = perfumeResult.nextRecipeNumber;

    // 4. НОВОЕ: Парсим ароматические масла
    const oilResult = parseAromaticOils(text, vocabularies, nextRecipeNumber);
    allRecipes.push(...oilResult.recipes);
    nextRecipeNumber = oilResult.nextRecipeNumber;

    // 5. НОВОЕ: Парсим нумерованные рецепты (ликёрные масла и бальзамы)
    const numberedResult = parseNumberedRecipes(text, vocabularies, nextRecipeNumber);
    allRecipes.push(...numberedResult.recipes);

  } catch (parseError) {
    console.error('✗ Ошибка парсинга:', parseError.message);
  }

  return allRecipes;
}

// Основная функция
try {
  // Получаем данные от Merge узла
  const allInputs = $input.all();

  console.log(`Получено элементов от Merge узла: ${allInputs.length}`);

  if (allInputs.length < 400) {
    return [{ json: { 
      error: `Недостаточно данных от Merge узла. Получено: ${allInputs.length}, ожидалось ~486`,
      status: 'failed'
    }}];
  }

  // Разделяем данные: ищем элемент с большим текстом
  let vocabularyData = [];
  let textData = null;

  for (const item of allInputs) {
    if (item?.json) {
      // Если это текстовые данные (большой объем текста)
      if (item.json.data && typeof item.json.data === 'string' && item.json.data.length > 50000) {
        textData = item.json.data;
        console.log(`Найден текст: ${textData.length} символов`);
      }
      // Если это словарный термин
      else if (item.json.category && item.json.term && item.json.term_index !== undefined) {
        vocabularyData.push(item.json);
      }
    }
  }

  console.log(`Словарей: ${vocabularyData.length}, текст: ${textData ? 'найден' : 'НЕ НАЙДЕН'}`);

  // Валидация данных
  if (vocabularyData.length === 0) {
    return [{ json: { 
      error: 'Словари не найдены в данных от Merge узла',
      status: 'failed'
    }}];
  }

  if (!textData) {
    return [{ json: { 
      error: 'Текстовые данные не найдены в данных от Merge узла',
      status: 'failed'
    }}];
  }

  // Обрабатываем словари
  console.log('\n=== ОБРАБОТКА СЛОВАРЕЙ ===');
  const vocabularies = processVocabularies(vocabularyData);

  // Парсим все рецепты
  console.log('\n=== ПОЛНЫЙ ПАРСИНГ РЕЦЕПТОВ ===');
  const allRecipes = await parseAllHistoricalRecipes(textData, vocabularies);

  if (allRecipes.length === 0) {
    return [{ json: { 
      error: 'Рецепты не найдены',
      status: 'completed_no_results'
    }}];
  }

  // Сортируем и считаем статистику
  allRecipes.sort((a, b) => a.number - b.number);

  const categoryStats = {};
  const sourceStats = {};

  allRecipes.forEach(recipe => {
    categoryStats[recipe.category] = (categoryStats[recipe.category] || 0) + 1;
    sourceStats[recipe.source_book] = (sourceStats[recipe.source_book] || 0) + 1;
  });

  console.log('\n=== ИТОГОВАЯ СТАТИСТИКА ===');
  console.log(`Обработано рецептов: ${allRecipes.length}`);
  console.log('По типам:');
  Object.entries(categoryStats).forEach(([cat, count]) => {
    console.log(`  ${cat}: ${count} рецептов`);
  });
  console.log('По источникам:');
  Object.entries(sourceStats).forEach(([source, count]) => {
    console.log(`  ${source}: ${count} рецептов`);
  });

  // Проверяем sparse vectors
  const vectorStats = {};
  const requiredCategories = ['categories', 'ingredients', 'measurements', 'spices_herbs', 'techniques'];

  requiredCategories.forEach(category => {
    vectorStats[category] = 0;
  });

  allRecipes.forEach(recipe => {
    Object.keys(recipe.sparse_vectors).forEach(category => {
      if (vectorStats[category] !== undefined) {
        vectorStats[category] += recipe.sparse_vectors[category].indices.length;
      }
    });
  });

  console.log('Статистика sparse vectors:');
  Object.entries(vectorStats).forEach(([category, count]) => {
    console.log(`  ${category}: ${count} совпадений`);
  });

  console.log('\n✅ ПОЛНЫЙ ПАРСИНГ ЗАВЕРШЕН УСПЕШНО');

  return allRecipes.map(recipe => ({ json: recipe }));

} catch (globalError) {
  console.error('✗ КРИТИЧЕСКАЯ ОШИБКА:', globalError.message);
  console.error('Stack:', globalError.stack);
  return [{ json: { 
    error: 'Critical parsing error',
    message: globalError.message,
    stack: globalError.stack,
    status: 'failed',
    timestamp: new Date().toISOString()
  }}];
}

// Code Node: Объединение sparse и dense векторов (ИСПРАВЛЕННЫЙ)
// Убираем function declaration, выполняем код напрямую

// Получаем данные запроса и ответ OpenAI
const openaiResponse = $input.last().json; // Ответ от OpenAI

// Извлекаем эмбеддинг
if (!openaiResponse.data || !Array.isArray(openaiResponse.data) || openaiResponse.data.length === 0) {
  throw new Error('Некорректный ответ от OpenAI');
}

const embedding = openaiResponse.data[0].embedding;
if (!Array.isArray(embedding)) {
  throw new Error('Эмбеддинг не является массивом');
}

const recipe = $('Code1').first().json.recipe_data;

// Подготавливаем sparse векторы
const sparseVectors = {};
if (recipe.sparse_vectors) {
  Object.keys(recipe.sparse_vectors).forEach(category => {
    const sparse = recipe.sparse_vectors[category];
    if (sparse && sparse.indices && sparse.values && sparse.indices.length > 0) {
      sparseVectors[category] = {
        indices: sparse.indices,
        values: sparse.values
      };
    }
  });
}

const uniqueId = recipe.number * 1000 + Date.now() % 1000;


// Создаем point для Qdrant
const point = {
  id:  Math.abs(uniqueId),  // ИСПРАВЛЕНО: используем числовой ID вместо строки
  vector: {
    dense: embedding,
    ...sparseVectors
  },
  payload: {
    recipe_id: recipe.id,  // Сохраняем оригинальный строковый ID в payload
    recipe_number: recipe.number,
    recipe_name: recipe.name,
    content: recipe.content,
    full_text: recipe.full_text,
    content_length: recipe.content?.length || 0,
    name_lower: recipe.name?.toLowerCase() || '',
    has_ingredients: !!sparseVectors.ingredients,
    has_spices_herbs: !!sparseVectors.spices_herbs,
    has_techniques: !!sparseVectors.techniques,
    has_measurements: !!sparseVectors.measurements,
    is_vodka: recipe.name?.toLowerCase().includes('водка') || false,
    is_rozolia: recipe.name?.toLowerCase().includes('розолия') || false,
    is_ratafia: recipe.name?.toLowerCase().includes('ратафия') || false,
    created_at: new Date().toISOString(),
    vector_dimension: embedding.length,
    sparse_categories: Object.keys(sparseVectors)
  }
};

console.log(`✅ Point создан для рецепта ${recipe.id} с числовым ID ${recipe.number}`);

// Возвращаем point для загрузки в Qdrant
return [{
  json: {
    points: [point]  // Qdrant ожидает массив points
  }
}];
